import React, { useEffect, useRef } from 'react';
import * as THREE from 'three';

export const Hero3D: React.FC = () => {
  const mountRef = useRef<HTMLDivElement>(null);

  useEffect(() => {
    if (!mountRef.current) return;

    // --- Scene Setup ---
    const width = mountRef.current.clientWidth;
    const height = mountRef.current.clientHeight;
    
    const scene = new THREE.Scene();
    // Wider FOV to see more of the flight path
    const camera = new THREE.PerspectiveCamera(50, width / height, 0.1, 100);
    camera.position.set(0, 0, 18); 

    const renderer = new THREE.WebGLRenderer({ alpha: true, antialias: true });
    renderer.setSize(width, height);
    renderer.setPixelRatio(Math.min(window.devicePixelRatio, 2));
    renderer.shadowMap.enabled = true;
    renderer.shadowMap.type = THREE.PCFSoftShadowMap;
    // Enable physical lighting
    renderer.toneMapping = THREE.ACESFilmicToneMapping;
    renderer.toneMappingExposure = 1.0;
    mountRef.current.appendChild(renderer.domElement);

    // --- Lighting ---
    const ambientLight = new THREE.AmbientLight(0xffffff, 0.4);
    scene.add(ambientLight);

    const mainLight = new THREE.DirectionalLight(0xffffff, 2.5);
    mainLight.position.set(10, 10, 15);
    mainLight.castShadow = true;
    mainLight.shadow.mapSize.width = 2048;
    mainLight.shadow.mapSize.height = 2048;
    scene.add(mainLight);
    
    // Blue rim light for sci-fi feel
    const rimLight = new THREE.SpotLight(0x38bdf8, 8);
    rimLight.position.set(-10, 5, 5);
    rimLight.lookAt(0, 0, 0);
    scene.add(rimLight);

    // Engine glow reflection light (orange/red)
    const engineLight = new THREE.PointLight(0xf43f5e, 2, 20);
    engineLight.position.set(5, -5, 5);
    scene.add(engineLight);

    // --- Rocket Construction ---
    const rocketGroup = new THREE.Group();
    scene.add(rocketGroup);

    // High quality materials
    const bodyMat = new THREE.MeshPhysicalMaterial({ 
      color: 0xffffff, 
      metalness: 0.3, 
      roughness: 0.2,
      clearcoat: 1.0,
      clearcoatRoughness: 0.1
    });
    const darkMetalMat = new THREE.MeshStandardMaterial({ 
      color: 0x1e293b, 
      metalness: 0.8, 
      roughness: 0.4 
    });
    const accentMat = new THREE.MeshStandardMaterial({ 
      color: 0xe11d48, // Red accent
      metalness: 0.5, 
      roughness: 0.3 
    });
    const glowMat = new THREE.MeshBasicMaterial({ color: 0x38bdf8 }); // Cyan glow

    // 1. Main Fuselage
    // Cylinder with slightly wider bottom
    const fuselageGeo = new THREE.CylinderGeometry(0.5, 0.7, 3.5, 32);
    const fuselage = new THREE.Mesh(fuselageGeo, bodyMat);
    fuselage.castShadow = true;
    fuselage.receiveShadow = true;
    rocketGroup.add(fuselage);

    // 2. Nose Cone (Ogive shape via Lathe)
    const nosePoints = [];
    for (let i = 0; i <= 10; i++) {
        const x = 0.5 * (1 - (i/10)**2); // Curve equation
        const y = i * 0.15;
        nosePoints.push(new THREE.Vector2(x, y));
    }
    const noseGeo = new THREE.LatheGeometry(nosePoints, 32);
    const nose = new THREE.Mesh(noseGeo, bodyMat);
    nose.position.y = 1.75; // Top of fuselage
    nose.castShadow = true;
    rocketGroup.add(nose);

    // 3. Side Boosters (2x)
    const boosterGeo = new THREE.CapsuleGeometry(0.25, 2, 4, 16);
    const leftBooster = new THREE.Mesh(boosterGeo, darkMetalMat);
    leftBooster.position.set(-0.7, -0.5, 0);
    rocketGroup.add(leftBooster);
    
    const rightBooster = new THREE.Mesh(boosterGeo, darkMetalMat);
    rightBooster.position.set(0.7, -0.5, 0);
    rocketGroup.add(rightBooster);

    // 4. Wings/Fins (4x swept back)
    const finShape = new THREE.Shape();
    finShape.moveTo(0, 0);
    finShape.lineTo(0.8, -0.5);
    finShape.lineTo(0.8, -1.2);
    finShape.lineTo(0, -0.8);
    const finGeo = new THREE.ExtrudeGeometry(finShape, { depth: 0.05, bevelEnabled: true, bevelThickness: 0.02, bevelSize: 0.02, bevelSegments: 2 });
    
    for (let i = 0; i < 4; i++) {
        const fin = new THREE.Mesh(finGeo, accentMat);
        fin.position.y = -0.5;
        fin.rotation.y = (Math.PI / 2) * i;
        fin.translateZ(0.6); // Push out from center cylinder
        rocketGroup.add(fin);
    }

    // 5. Engine Nozzle & Glow
    const nozzleGeo = new THREE.CylinderGeometry(0.4, 0.6, 0.5, 32, 1, true);
    const nozzle = new THREE.Mesh(nozzleGeo, darkMetalMat);
    nozzle.position.y = -2.0;
    rocketGroup.add(nozzle);

    const coreGlow = new THREE.Mesh(new THREE.CylinderGeometry(0.3, 0.1, 0.2, 16), new THREE.MeshBasicMaterial({ color: 0xffaa00 }));
    coreGlow.position.y = -2.1;
    rocketGroup.add(coreGlow);

    // 6. Cockpit Window
    const cockpitGeo = new THREE.SphereGeometry(0.25, 32, 16, 0, Math.PI * 2, 0, Math.PI/2);
    const cockpit = new THREE.Mesh(cockpitGeo, glowMat);
    cockpit.rotation.x = -Math.PI / 2;
    cockpit.position.set(0, 1.0, 0.45);
    cockpit.scale.set(1, 2, 0.5);
    rocketGroup.add(cockpit);

    // 7. Hitbox
    const hitbox = new THREE.Mesh(
        new THREE.CylinderGeometry(1.5, 1.5, 6, 8),
        new THREE.MeshBasicMaterial({ visible: false })
    );
    rocketGroup.add(hitbox);

    // Initial Position (Right side of screen)
    // At z=18 camera, x=5 is roughly the right column area
    const HOME_POS = new THREE.Vector3(5, 0, 0);
    rocketGroup.position.copy(HOME_POS);
    rocketGroup.rotation.set(0, 0, Math.PI / 6); // Tilted

    // --- Particle System (Exhaust) ---
    const particles: { mesh: THREE.Mesh; life: number; velocity: THREE.Vector3; maxLife: number }[] = [];
    const particleGeo = new THREE.SphereGeometry(1, 8, 8); // Base geometry, scaled down
    const particleMat = new THREE.MeshBasicMaterial({ color: 0xffaa00, transparent: true, opacity: 0.8 });

    // Helper: spawn particle with a specific direction and speed
    const spawnParticle = (pos: THREE.Vector3, direction: THREE.Vector3, speed: number) => {
       const mesh = new THREE.Mesh(particleGeo, particleMat.clone());
       mesh.position.copy(pos);
       // Random offset at source
       mesh.position.add(new THREE.Vector3((Math.random()-0.5)*0.2, (Math.random()-0.5)*0.2, (Math.random()-0.5)*0.2));
       
       mesh.scale.setScalar(0.1 + Math.random() * 0.1);
       scene.add(mesh);
       
       const maxLife = 0.5 + Math.random() * 0.5;
       
       // Velocity is direction * speed + random spread
       const spread = 0.05;
       const velocity = direction.clone().multiplyScalar(speed);
       velocity.x += (Math.random() - 0.5) * spread;
       velocity.y += (Math.random() - 0.5) * spread;
       velocity.z += (Math.random() - 0.5) * spread;

       particles.push({
         mesh,
         life: maxLife,
         maxLife,
         velocity
       });
    };

    // --- Animation Logic ---
    // Path: Loops around the entire hero section
    const pathPoints = [
      HOME_POS.clone(),                    // Start (Right)
      new THREE.Vector3(2, 3, 2),          // Up and Center
      new THREE.Vector3(-4, 2, 4),         // Top Left (Close to cam)
      new THREE.Vector3(-8, 0, 0),         // Far Left
      new THREE.Vector3(-4, -4, -4),       // Bottom Left (Behind)
      new THREE.Vector3(4, -3, -6),        // Bottom Right (Far Behind)
      new THREE.Vector3(7, -1, -2),        // Approach Home
      HOME_POS.clone()                     // Land
    ];
    const flightPath = new THREE.CatmullRomCurve3(pathPoints);
    flightPath.closed = false;
    flightPath.tension = 0.5;

    const raycaster = new THREE.Raycaster();
    const mouse = new THREE.Vector2(-999, -999); // Offscreen default
    let isHovered = false;
    let isFlying = false;
    let progress = 0;
    const flightSpeed = 0.004; // Slower for majesty
    let time = 0;

    const onMouseMove = (event: MouseEvent) => {
      const rect = renderer.domElement.getBoundingClientRect();
      mouse.x = ((event.clientX - rect.left) / rect.width) * 2 - 1;
      mouse.y = -((event.clientY - rect.top) / rect.height) * 2 + 1;
    };

    mountRef.current.addEventListener('mousemove', onMouseMove);

    // --- Animation Loop ---
    const animate = () => {
      requestAnimationFrame(animate);
      time += 0.015;

      // Raycasting
      raycaster.setFromCamera(mouse, camera);
      const intersects = raycaster.intersectObject(hitbox);
      const isHit = intersects.length > 0;
      
      if (isHit && !isHovered) {
          isHovered = true;
          document.body.style.cursor = 'pointer';
      } else if (!isHit && isHovered) {
          isHovered = false;
          document.body.style.cursor = 'default';
      }

      // Trigger Launch
      if (isHovered && !isFlying) {
        isFlying = true;
        progress = 0;
      }

      // Calculate the world direction pointing out of the back of the rocket (Thrust direction)
      // Rocket is built along Y, so Bottom is (0, -1, 0) local.
      const thrustDir = new THREE.Vector3(0, -1, 0);
      thrustDir.applyQuaternion(rocketGroup.quaternion);

      if (isFlying) {
        // Flight Mode
        progress += flightSpeed;
        
        if (progress > 1) {
          // Landed
          progress = 1;
          isFlying = false;
          
          // Reset smoothly
          rocketGroup.position.copy(HOME_POS);
          rocketGroup.rotation.set(0, 0, Math.PI / 6);
        } else {
          // Follow Path
          const currentPos = flightPath.getPointAt(progress);
          const nextPos = flightPath.getPointAt(Math.min(progress + 0.01, 1));
          
          rocketGroup.position.copy(currentPos);
          rocketGroup.lookAt(nextPos);
          // Correct orientation: Cylinder builds along Y, LookAt uses Z. 
          // Rotate X +90deg to point Top along Z.
          rocketGroup.rotateX(Math.PI / 2);
          
          // Add banking (roll) based on turn
          // Simple bank: tilt z based on x change
          const turnFactor = (currentPos.x - nextPos.x) * 0.5;
          rocketGroup.rotateZ(turnFactor);

          // Heavy Engine Particles
          const enginePos = new THREE.Vector3(0, -2.2, 0);
          enginePos.applyMatrix4(rocketGroup.matrixWorld);
          
          // Recalculate thrust dir after rotation updates
          const flightThrust = new THREE.Vector3(0, -1, 0).applyQuaternion(rocketGroup.quaternion);
          
          // Spawn multiple for density, pushing "backwards"
          for(let k=0; k<5; k++) spawnParticle(enginePos, flightThrust, 0.4);
        }
      } else {
        // Idle Hover Mode
        rocketGroup.position.y = HOME_POS.y + Math.sin(time * 1.5) * 0.3;
        rocketGroup.rotation.z = Math.PI / 6 + Math.sin(time) * 0.05;
        rocketGroup.rotation.y = Math.sin(time * 0.5) * 0.1;
        
        // Idle Particles (Smoke)
        if (Math.random() > 0.7) {
            const enginePos = new THREE.Vector3(0, -2.2, 0);
            enginePos.applyMatrix4(rocketGroup.matrixWorld);
            // In idle, thrust is just local down converted to world
            const idleThrust = new THREE.Vector3(0, -1, 0).applyQuaternion(rocketGroup.quaternion);
            spawnParticle(enginePos, idleThrust, 0.1);
        }
      }

      // Particles Update
      for (let i = particles.length - 1; i >= 0; i--) {
        const p = particles[i];
        p.life -= 0.015;
        if (p.life <= 0) {
          scene.remove(p.mesh);
          particles.splice(i, 1);
        } else {
          p.mesh.position.add(p.velocity);
          // Expand smoke
          p.mesh.scale.setScalar((p.maxLife - p.life) * 1.5); // Grow over time
          
          const m = p.mesh.material as THREE.MeshBasicMaterial;
          m.opacity = (p.life / p.maxLife) * 0.6;
          
          // Color shift: Blue/White (hot) -> Orange -> Grey (smoke)
          const lifeRatio = p.life / p.maxLife;
          if (lifeRatio > 0.8) m.color.setHex(0xaaddff); // Blueish hot
          else if (lifeRatio > 0.5) m.color.setHex(0xffaa00); // Orange
          else m.color.setHex(0x555555); // Grey
        }
      }

      renderer.render(scene, camera);
    };

    animate();

    const handleResize = () => {
        if (!mountRef.current) return;
        const w = mountRef.current.clientWidth;
        const h = mountRef.current.clientHeight;
        camera.aspect = w / h;
        camera.updateProjectionMatrix();
        renderer.setSize(w, h);
    };
    window.addEventListener('resize', handleResize);

    return () => {
        window.removeEventListener('resize', handleResize);
        if (mountRef.current) {
            mountRef.current.removeEventListener('mousemove', onMouseMove);
            mountRef.current.removeChild(renderer.domElement);
        }
        renderer.dispose();
    };
  }, []);

  return (
    <div ref={mountRef} className="w-full h-full pointer-events-auto" />
  );
};